const root = $input.first().json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const payload = (body.payload && typeof body.payload === 'object') ? body.payload : {};
const trigger = String(payload.trigger || '');
const alert_prefix = trigger === 'human_handoff' ? '[HANDOFF]' : '[HOT]';
return [{
  json: {
    event_type: body.event_type || root.event_type || '',
    tenant_id: body.tenant_id || root.tenant_id || '',
    entity_id: body.entity_id || root.entity_id || payload.lead_id || '',
    timestamp: body.timestamp || root.timestamp || '',
    payload,
    alert_prefix,
  }
}];
